package com.spotifyclone.catalog.poc;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.util.UUID;

/**
 * POC fixture — an event in the log. The sequence number is the primary key
 * and is generated by the database (IDENTITY), which guarantees a monotonic,
 * gap-free-per-session ordering for replay.
 *
 * <p>NOT production code.
 */
@Entity
@Table(name = "poc_jam_event")
public class JamEventEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "seq", nullable = false, updatable = false)
    private Long seq;

    @Column(name = "session_id", nullable = false)
    private UUID sessionId;

    @Column(name = "event_type", nullable = false)
    private String eventType;

    @Column(name = "payload", nullable = false, columnDefinition = "TEXT")
    private String payload;

    protected JamEventEntity() {
        // JPA
    }

    public JamEventEntity(UUID sessionId, String eventType, String payload) {
        this.sessionId = sessionId;
        this.eventType = eventType;
        this.payload = payload;
    }

    public Long getSeq() {
        return seq;
    }

    public UUID getSessionId() {
        return sessionId;
    }

    public String getEventType() {
        return eventType;
    }

    public String getPayload() {
        return payload;
    }
}
